public int[][] kClosest(int[][] points, int k) {
    // Max-heap by squared distance (largest distance on top).
    PriorityQueue<int[]> heap =
        new PriorityQueue<>((a, b) -> dist(b) - dist(a));
    for (int[] p : points) {
        heap.offer(p);
        if (heap.size() > k) {
            heap.poll();
        }
    }
    int[][] res = new int[k][2];
    for (int i = 0; i < k; i++) {
        res[i] = heap.poll();
    }
    return res;
}

private int dist(int[] p) {
    return p[0] * p[0] + p[1] * p[1];
}

