import heapq

def kClosest(self, points: list[list[int]], k: int) -> list[list[int]]:
    heap: list[tuple[int, int, int]] = []  # (-dist, x, y) → max-heap
    for x, y in points:
        d = x * x + y * y
        heapq.heappush(heap, (-d, x, y))
        if len(heap) > k:
            heapq.heappop(heap)
    return [[x, y] for _, x, y in heap]

