public int[][] kClosest(int[][] points, int k) {
    int lo = 0, hi = points.length - 1;
    while (lo < hi) {
        int p = partition(points, lo, hi);
        if (p == k) break;
        else if (p < k) lo = p + 1;
        else hi = p - 1;
    }
    return Arrays.copyOfRange(points, 0, k);
}

private int partition(int[][] pts, int lo, int hi) {
    int pivot = dist(pts[hi]);
    int i = lo;
    for (int j = lo; j < hi; j++) {
        if (dist(pts[j]) <= pivot) {
            swap(pts, i++, j);
        }
    }
    swap(pts, i, hi);
    return i;
}

private int dist(int[] p) { return p[0]*p[0] + p[1]*p[1]; }

private void swap(int[][] pts, int a, int b) {
    int[] t = pts[a]; pts[a] = pts[b]; pts[b] = t;
}

